1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: { op: string; items: { type: string }[] }[];
4	};
5	
6	export type ScenarioResult = {
7	  results: { premium: number }[];
8	};
9	
10	const PROCESSING_FEE = 5;
11	
12	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
13	
14	const BASE_PREMIUMS: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	};
20	
21	// Percentages stay in integer percent points: multiply first, divide by 100
22	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
23	// a sword and breaks the ceil.
24	const percentOf = (amount: number, percent: number): number =>
25	  (amount * percent) / 100;
26	
27	const quote = (items: { type: string }[]): number => {
28	  const basePremium = items.reduce(
29	    (sum, item) => sum + BASE_PREMIUMS[item.type],
30	    0,
31	  );
32	
33	  const firstInsuranceSurcharge = percentOf(
34	    basePremium,
35	    FIRST_INSURANCE_SURCHARGE_PERCENT,
36	  );
37	
38	  return Math.ceil(basePremium + firstInsuranceSurcharge) + PROCESSING_FEE;
39	};
40	
41	export const runScenario = (scenario: Scenario): ScenarioResult => ({
42	  results: scenario.steps.map((step) => ({ premium: quote(step.items) })),
43	});
