const policyBase = items.reduce(
  (sum, item) => sum + BASE_PREMIUMS[item.type],
  0,
);

const firstInsuranceSurcharge = percentOf(
  policyBase,
  FIRST_INSURANCE_SURCHARGE_PERCENT,
);

return Math.ceil(policyBase + firstInsuranceSurcharge) + PROCESSING_FEE;

// Rounding is in the MHPCO's favour: premiums round up.
const premiumBeforeFee = Math.ceil(policyBase + firstInsuranceSurcharge);

return premiumBeforeFee + PROCESSING_FEE;
